import { ApolloClient, InMemoryCache, createHttpLink, ApolloLink } from '@apollo/client';

// Create HTTP link
const httpLink = createHttpLink({
  uri: 'http://localhost:8000/graphql',
  credentials: 'same-origin',
});

// Auth middleware to add token to headers
const authMiddleware = new ApolloLink((operation, forward) => {
  // Get the authentication token from local storage if it exists
  const token = localStorage.getItem('token');

  // Add the authorization header to the request
  operation.setContext(({ headers = {} }) => ({
    headers: {
      ...headers,
      authorization: token ? `Bearer ${token}` : '',
    }
  }));

  return forward(operation);
});

// Log any GraphQL errors or network errors that occurred
const errorLink = new ApolloLink((operation, forward) => {
  return forward(operation).map(response => {
    if (response.errors) {
      console.error('GraphQL Errors:', response.errors);

      // Handle authentication errors
      const authError = response.errors.find(
        error => error.extensions?.code === 'UNAUTHENTICATED'
      );

      if (authError) {
        // Clear the invalid token and redirect to login
        localStorage.removeItem('token');
        window.location.href = '/login';
      }
    }
    return response;
  });
});

// Create the Apollo Client instance with cache configuration
const client = new ApolloClient({
  link: ApolloLink.from([
    authMiddleware,
    errorLink,
    httpLink,
  ]),
  cache: new InMemoryCache({
    typePolicies: {
      Query: {
        fields: {
          // Add any specific field policies here if needed
        },
      },
    },
  }),
  defaultOptions: {
    watchQuery: {
      fetchPolicy: 'network-only',
      errorPolicy: 'all',
    },
    query: {
      fetchPolicy: 'network-only',
      errorPolicy: 'all',
    },
    mutate: {
      errorPolicy: 'all',
    },
  },
});

// Add global error handler
const errorHandler = {
  onError: (error) => {
    console.error('Apollo Client Error:', error);
  },
};

// Add error handler to the client's default options
client.defaultOptions = {
  ...client.defaultOptions,
  watchQuery: {
    ...client.defaultOptions.watchQuery,
    context: errorHandler,
  },
  query: {
    ...client.defaultOptions.query,
    context: errorHandler,
  },
  mutate: {
    ...client.defaultOptions.mutate,
    context: errorHandler,
  },
};

export default client;
